/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: expectPrivate, call, json
 *   Constants: ids, rowWord, rowTitles, flags, previous, personalization
 *   Variables: harness, server, base, userToken, adminToken
 * Tests
 *   - no listener, legacy, Search, Page, Follow, Library or Playlist response carries an Album's expected tracklist, for any caller
 *   - expected tracklist rows never enter Search, the Album order or listener numbering
 *   - the listener reads that load whole Album documents exclude the expected tracklist from their queries and leave it stored
 * @end-catalog */

/**
 * An Album's expected tracklist is administrator information: a ready public Album that stores one, credited to a followed Artist
 * and a label, saved to the Library, played, placed in a playlist through its member and shown by a manual, an artist and a
 * followed-release carousel, never shows the key or any row title in any listener v1, legacy content, Search, Follow, Page, Library
 * or Playlist response, for an anonymous caller, a listener or an administrator in User view. Its rows never enter Search, the
 * Album order or listener numbering, and the listener reads that load whole Album documents leave the field in the database.
 * Share, friend status and Room responses are scanned in their own harnesses. All names, IDs and accounts are synthetic.
 */
import assert from 'node:assert/strict';
import type { Server } from 'node:http';
import os from 'node:os';
import path from 'node:path';
import { after, before, test } from 'node:test';
import { ObjectId, type Document } from 'mongodb';
import { createApp } from '../../src/app';
import { getDb } from '../../src/infrastructure/database';
import { createSession } from '../../src/services/auth/authSessionService';
import { startMongoReplicaSet, type MongoReplicaSetHarness } from '../support/mongoReplicaSet';

const ids = {
    user: new ObjectId(), admin: new ObjectId(), artist: new ObjectId(), label: new ObjectId(), album: new ObjectId(), track: new ObjectId(),
    artistCarousel: new ObjectId(), manualCarousel: new ObjectId(), followedCarousel: new ObjectId(), trackCarousel: new ObjectId(),
    grid: new ObjectId(), artistPlacement: new ObjectId(), manualPlacement: new ObjectId(), followedPlacement: new ObjectId(), gridPlacement: new ObjectId(),
    libraryPlacement: new ObjectId()
};
// Every row title shares one word that no listener-visible title uses, so a row title anywhere in a payload is a leak.
const rowWord = 'Unheard';
const rowTitles = ['Unheard Synthetic Row One', 'Unheard Synthetic Row Two', 'Unheard Synthetic Row Three'];
const flags = { FINITUDE_ARTIST_FOLLOWS_ENABLED: 'true' };
const previous = Object.fromEntries(Object.keys(flags).map(key => [key, process.env[key]]));
const personalization = { 'X-Finitude-Personalization-Version': '1' };
let harness: MongoReplicaSetHarness, server: Server, base = '', userToken = '', adminToken = '';

/** Fails when a payload carries the expected tracklist key anywhere or any row title. */
function expectPrivate(label: string, payload: unknown) {
    const text = typeof payload === 'string' ? payload : JSON.stringify(payload);
    assert.equal(text.includes('expectedTracklist'), false, `${label} exposed the expectedTracklist key`);
    assert.equal(text.includes(rowWord), false, `${label} exposed an expected tracklist row title`);
}
const call = (route: string, token = '', method = 'GET', body?: unknown, headers: Record<string, string> = {}) => fetch(base + route, {
    method, headers: { ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(body === undefined ? {} : { 'Content-Type': 'application/json' }), ...headers },
    ...(body === undefined ? {} : { body: JSON.stringify(body) })
});
const json = async (route: string, token = '', headers: Record<string, string> = {}) => {
    const response = await call(route, token, 'GET', undefined, headers);
    assert.equal(response.status, 200, route);
    return response.json() as Promise<any>;
};

before(async () => {
    Object.assign(process.env, flags);
    harness = await startMongoReplicaSet('archtree-expected-tracklist-privacy-test');
    const db = getDb()!, credit = (subjectType: string, subjectId: ObjectId, role: string, order: number) => ({ creditId: `credit_${role}_${order}`, subjectType, subjectId: subjectId.toHexString(), role, order });
    const now = new Date(), today = { year: now.getUTCFullYear(), month: now.getUTCMonth() + 1, day: now.getUTCDate() };
    const user = { _id: ids.user, email: 'tracklist-listener@example.test', role: 'user', emailVerified: true };
    const admin = { _id: ids.admin, email: 'tracklist-admin@example.test', role: 'admin', emailVerified: true };
    await db.collection('users').insertMany([user, admin]);
    await db.collection('artists').insertOne({ _id: ids.artist, name: 'Tracklist Privacy Artist', bio: 'Synthetic biography', coverArtUrl: '', albumIds: [ids.album.toHexString()], lifecycleStatus: 'ready' });
    await db.collection('organizations').insertOne({ _id: ids.label, name: 'Tracklist Privacy Label', organizationType: 'label', description: '', lifecycleStatus: 'ready' });
    // The stored value is raw: three rows, of which only the first has a member, at Disc 1 Track 1.
    await db.collection('albums').insertOne({ _id: ids.album, title: 'Tracklist Privacy Album', coverArtUrl: '', audioTrackIds: [ids.track.toHexString()], releaseDate: today, lifecycleStatus: 'ready',
        credits: [credit('artist', ids.artist, 'primary', 0), credit('organization', ids.label, 'label', 1)], attributionStatus: 'documented', creditRevision: 1,
        expectedTracklist: { source: 'musicbrainz', appliedAt: new Date('2026-10-20T08:00:00.000Z'), rows: [
            { discNumber: 1, trackNumber: 1, title: rowTitles[0], durationMs: 190_000 },
            { discNumber: 1, trackNumber: 2, title: rowTitles[1], durationMs: null },
            { discNumber: 2, trackNumber: 1, title: rowTitles[2], durationMs: 201_000 }
        ] } });
    await db.collection('audioTracks').insertOne({ _id: ids.track, title: 'Tracklist Privacy Track', artistIds: [ids.artist.toHexString()], albumId: ids.album.toHexString(), discNumber: 1, trackNumber: 1,
        duration: '03:10', coverArtUrl: '', mediaType: 'audio', uploadStatus: 'ready', publicationStatus: 'ready', s3Key: ids.track.toHexString(),
        credits: [credit('artist', ids.artist, 'primary', 0)], attributionStatus: 'documented', creditRevision: 1 });
    await db.collection('carousels').insertMany([
        { _id: ids.artistCarousel, name: 'Artist Albums', mode: 'artist', items: [], artistConfig: { artistId: ids.artist.toHexString(), contentType: 'album', sort: 'titleAsc', limit: 5 } },
        { _id: ids.manualCarousel, name: 'Manual Albums', mode: 'manual', contentType: 'album', items: [{ contentType: 'album', contentId: ids.album.toHexString(), order: 0 }] },
        { _id: ids.followedCarousel, name: 'Followed Releases', mode: 'personalized', personalizedConfig: { source: 'followedArtistReleases', limit: 12 }, items: [] },
        // The Library page places only the member, so its expanded read loads the Album as a linked Album.
        { _id: ids.trackCarousel, name: 'Manual Tracks', mode: 'manual', contentType: 'audioTrack', items: [{ contentType: 'audioTrack', contentId: ids.track.toHexString(), order: 0 }] }
    ]);
    await db.collection('contentCollections').insertOne({ _id: ids.grid, name: 'Grid Albums', presentation: 'grid', mode: 'manual', contentType: 'album',
        items: [{ contentType: 'album', contentId: ids.album.toHexString(), order: 0 }] });
    const placement = (itemId: ObjectId, carouselId: ObjectId, order: number) => ({ itemId: itemId.toHexString(), itemType: 'carousel', carouselId: carouselId.toHexString(), order });
    await db.collection('pages').insertMany([
        { slug: 'home', title: 'Listen Now', items: [placement(ids.artistPlacement, ids.artistCarousel, 0), placement(ids.manualPlacement, ids.manualCarousel, 1),
            placement(ids.followedPlacement, ids.followedCarousel, 2), { itemId: ids.gridPlacement.toHexString(), itemType: 'grid', collectionId: ids.grid.toHexString(), order: 3 }] },
        { slug: 'library', title: 'Library', items: [placement(ids.libraryPlacement, ids.trackCarousel, 0)] }
    ]);
    userToken = (await createSession(user)).accessToken; adminToken = (await createSession(admin)).accessToken;
    const app = createApp({ listenerDistPath: path.join(os.tmpdir(), 'archtree-expected-tracklist-privacy-missing') });
    server = await new Promise(resolve => { const listening = app.listen(0, '127.0.0.1', () => resolve(listening)); });
    const address = server.address(); assert.ok(address && typeof address !== 'string'); base = `http://127.0.0.1:${address.port}`;
    // The listener and the administrator follow the Artist, save and play the Album and its member; each response is checked too.
    const album = ids.album.toHexString(), track = ids.track.toHexString(), artist = ids.artist.toHexString();
    for (const token of [userToken, adminToken]) {
        const follow = await call(`/content/me/artist-follows/${artist}`, token, 'PUT', {});
        assert.ok(follow.status < 300, `follow ${follow.status}`); expectPrivate('follow', await follow.text());
        expectPrivate('follow status', await (await call('/content/me/artist-follows/status', token, 'POST', { artistIds: [artist] })).text());
        for (const [contentType, contentId] of [['album', album], ['audioTrack', track]]) {
            const save = await call(`/content/me/saves/${contentType}/${contentId}`, token, 'PUT', {});
            assert.ok(save.status < 300, `save ${contentType} ${save.status}`); expectPrivate(`save ${contentType}`, await save.text());
            const played = await call('/content/me/recently-played', token, 'POST', { contentType, contentId });
            assert.equal(played.status, 200, `play ${contentType}`); expectPrivate(`play ${contentType}`, await played.text());
        }
        expectPrivate('save status', await (await call('/content/me/saves/status', token, 'POST', { items: [{ contentType: 'album', contentId: album }] })).text());
    }
});
after(async () => {
    await new Promise<void>(resolve => server ? server.close(() => resolve()) : resolve()); await harness?.stop();
    for (const [key, value] of Object.entries(previous)) { if (value === undefined) delete process.env[key]; else process.env[key] = value; }
});

test('no listener, legacy, Search, Page, Follow, Library or Playlist response carries an Album\'s expected tracklist, for any caller', async () => {
    const album = ids.album.toHexString(), track = ids.track.toHexString(), artist = ids.artist.toHexString(), label = ids.label.toHexString();
    const created = await call('/content/me/playlists', userToken, 'POST', { name: 'Synthetic Playlist' }, { 'Idempotency-Key': 'tracklist-playlist-create' });
    assert.ok(created.status < 300, `playlist ${created.status}`);
    const playlistBody: any = await created.json(); expectPrivate('playlist create', playlistBody);
    const playlist = playlistBody.playlist?.id ?? playlistBody.id;
    assert.ok(playlist, JSON.stringify(playlistBody));
    const added = await call(`/content/me/playlists/${playlist}/items`, userToken, 'POST', { audioTrackId: track },
        { 'Idempotency-Key': 'tracklist-playlist-add', 'If-Match': created.headers.get('etag') ?? `"${playlistBody.playlist?.revision ?? playlistBody.revision ?? 1}"` });
    assert.ok(added.status < 300, `playlist add ${added.status}`);
    expectPrivate('playlist add', await added.text());

    const listener = ['/api/listener/v1/home', '/api/listener/v1/search?q=Tracklist', `/api/listener/v1/albums/${album}`, `/api/listener/v1/artists/${artist}`,
        `/api/listener/v1/organizations/${label}`, `/api/listener/v1/tracks/${track}`, `/api/listener/v1/pages/home/items/${ids.gridPlacement.toHexString()}`];
    // `/content/audioTrack/:id` only redirects to the audio stream, so it carries no metadata to scan.
    const legacy = ['/content/artists', `/content/artist/${artist}`, `/content/organization/${label}`, '/content/albums', `/content/album/${album}`, '/content/audioTracks',
        '/content/search?q=Tracklist', '/content/pages', '/content/pages/home', '/content/pages/home/expanded', '/content/pages/library/expanded'];
    const personal = ['/api/listener/v1/library', '/api/listener/v1/recently-played', '/content/me/library', '/content/me/playlists', `/content/me/playlists/${playlist}`];
    // Only a follower that negotiates personalization receives the followed-release section.
    const followed = ['/api/listener/v1/home', '/content/pages/home/expanded'];
    let checked = 0;
    for (const [caller, token] of [['anonymous', ''], ['listener', userToken], ['administrator in User view', adminToken]] as const) {
        const routes: [string, Record<string, string>][] = [...listener, ...legacy, ...(token ? personal : [])].map(route => [route, {}]);
        if (token) routes.push(...followed.map((route): [string, Record<string, string>] => [route, personalization]));
        for (const [route, headers] of routes) {
            const response = await call(route, token, 'GET', undefined, headers);
            expectPrivate(`${caller} ${route}`, await response.text());
            if (response.status === 200) checked++;
        }
    }
    // Every route answers 200 except the anonymous Library page (401) and the listener's playlist read by the administrator (404).
    assert.ok(checked >= 66, `only ${checked} responses answered 200`);

    // The scan read real payloads: every surface that can show the Album did show it.
    for (const token of [userToken, adminToken]) {
        const home = await json('/api/listener/v1/home', token, personalization);
        const section = (title: string) => home.sections.find((value: any) => value.title === title);
        for (const title of ['Artist Albums', 'Manual Albums', 'Followed Releases']) {
            assert.deepEqual(section(title)?.items.map((item: any) => [item.contentType, item.id]), [['album', album]], title);
        }
        const expandedHome = await json('/content/pages/home/expanded', token, personalization);
        assert.deepEqual(expandedHome.included.albums.map((value: any) => value._id), [album]);
        const expandedLibrary = await json('/content/pages/library/expanded', token);
        assert.deepEqual(expandedLibrary.included.albums.map((value: any) => value._id), [album], 'the linked Album of a placed member');
        const library = await json('/content/me/library', token);
        assert.deepEqual(library.items.map((item: any) => [item.contentType, item.album?._id ?? item.audioTrack?._id]).sort(), [['album', album], ['audioTrack', track]]);
        assert.ok(JSON.stringify(await json('/api/listener/v1/library', token)).includes(album));
        assert.ok(JSON.stringify(await json('/api/listener/v1/recently-played', token)).includes(album));
    }
    const grid = await json(`/api/listener/v1/pages/home/items/${ids.gridPlacement.toHexString()}`);
    assert.deepEqual(grid.items.map((item: any) => [item.contentType, item.contentId]), [['album', album]]);
    assert.deepEqual(grid.included.albums.map((value: any) => value.id), [album]);
    const albumView = await json(`/api/listener/v1/albums/${album}`);
    assert.match(JSON.stringify(albumView), /Tracklist Privacy Artist/);
    assert.match(JSON.stringify(albumView), /Tracklist Privacy Label/);
});

test('expected tracklist rows never enter Search, the Album order or listener numbering', async () => {
    const album = ids.album.toHexString(), track = ids.track.toHexString();
    // A row-title word finds nothing, while the Album's own title word still finds the Album.
    const listResults = (payload: Record<string, unknown>) => Object.entries(payload).filter(([, value]) => Array.isArray(value)) as [string, unknown[]][];
    for (const route of [`/api/listener/v1/search?q=${rowWord}`, `/content/search?q=${rowWord}`]) {
        const results = listResults(await json(route));
        assert.ok(results.length >= 2, `${route} answered no result lists`);
        for (const [key, value] of results) assert.deepEqual(value, [], `${route} ${key}`);
    }
    for (const route of ['/api/listener/v1/search?q=Tracklist%20Privacy%20Album', '/content/search?q=Tracklist%20Privacy%20Album']) {
        assert.deepEqual((await json(route)).albums.map((value: any) => value.id ?? value._id), [album], route);
    }
    // Only the member is listed and numbered: the two missing-file rows add no listener track.
    const listenerAlbum = await json(`/api/listener/v1/albums/${album}`);
    assert.equal(listenerAlbum.tracks.length, 1);
    assert.equal(listenerAlbum.tracks[0].id, track);
    assert.deepEqual((await json(`/content/album/${album}`)).album.audioTrackIds, [track]);
    assert.deepEqual((await getDb()!.collection('albums').findOne({ _id: ids.album }))!.audioTrackIds, [track]);
});

test('the listener reads that load whole Album documents exclude the expected tracklist from their queries and leave it stored', async () => {
    const db = getDb()!, album = ids.album.toHexString();
    /** Profiles one route and returns its Album finds and aggregates, and its MediaTrack aggregates (which look up Albums). */
    const routeCommands = async (route: string, headers: Record<string, string> = {}) => {
        const since = new Date();
        await db.command({ profile: 2 });
        try { assert.equal((await call(route, userToken, 'GET', undefined, headers)).status, 200, route); }
        finally { await db.command({ profile: 0 }); }
        return (await db.collection('system.profile').find({ ts: { $gte: since }, $or: [
            { ns: `${db.databaseName}.albums`, 'command.find': 'albums' }, { ns: `${db.databaseName}.albums`, 'command.aggregate': 'albums' },
            { ns: `${db.databaseName}.audioTracks`, 'command.aggregate': 'audioTracks' }
        ] }).toArray()).map(entry => entry.command as Document);
    };
    const excluded = (command: Document) => Boolean(command.find) && command.projection?.expectedTracklist === 0;
    // The artist carousel's cursor is the only sorted Album find that matches Credits; the Page and Library reads match IDs only.
    const artistCursor = (command: Document) => excluded(command) && Boolean(command.sort) && JSON.stringify(command.filter).includes('"$elemMatch"');
    const byIds = (command: Document) => excluded(command) && Array.isArray(command.filter?._id?.$in);
    const unsets = (command: Document) => JSON.stringify(command.pipeline ?? []).includes('{"$unset":"expectedTracklist"}');

    // Each of the four whole-document readers ran with its exclusion: the expanded Page's placed and linked Albums, the artist
    // carousel's cursor, the Library's saved and linked Albums, and the followed-release Album qualification (the Album aggregate,
    // and the MediaTrack aggregate that qualifies a member's Album inside its lookup).
    const expandedHome = await routeCommands('/content/pages/home/expanded', personalization);
    assert.ok(expandedHome.some(artistCursor), 'artist carousel cursor');
    assert.ok(expandedHome.some(command => byIds(command) && JSON.stringify(command.filter).includes(album)), 'placed Albums');
    assert.ok(expandedHome.some(command => command.aggregate === 'albums' && unsets(command)), 'followed-release Album aggregate');
    assert.ok(expandedHome.some(command => command.aggregate === 'audioTracks' && JSON.stringify(command.pipeline).includes('"from":"albums"') && unsets(command)),
        'followed-release member Album lookup');
    assert.equal((await routeCommands('/content/pages/library/expanded')).filter(byIds).length, 1, 'linked Albums of a Page');
    assert.equal((await routeCommands('/api/listener/v1/library')).filter(byIds).length, 2, 'saved and linked Library Albums');
    // The listener Home runs the same readers.
    const home = await routeCommands('/api/listener/v1/home', personalization);
    assert.ok(home.some(command => command.aggregate === 'albums' && unsets(command)));
    assert.ok(home.some(artistCursor));
    // No read changes the stored value.
    assert.equal((await db.collection('albums').findOne({ _id: ids.album }))!.expectedTracklist.rows.length, 3);
});
